import numpy as np

def particular_sinusoid(p, q, w, amp):
    """(A, B) with y_p = A cos(wt) + B sin(wt) solving y'' + p y' + q y = amp sin(wt)."""
    M = np.array([[q - w * w, p * w], [-p * w, q - w * w]], dtype=float)
    if abs(np.linalg.det(M)) < 1e-12:
        raise ValueError("resonance: the guess has no solution")
    A, B = np.linalg.solve(M, [0.0, amp])
    return (float(A), float(B))
